// Some portions generated by Claude
import type { Binding, SparqlValue } from "./explorer-types.ts";
import { repositoryScope } from "./repository-identity.ts";

/**
 * "Add to graph" on the other Workbench pages (scripts/ts/graphAdditions.ts) queues resources, statements and
 * queries in localStorage under this prefix plus a versioned server/repository tuple; the Graph page takes them when it opens
 * and whenever another tab changes the queue. Terms are N-Triples terms.
 */
export const ADDITIONS_PREFIX = "rdf4j-workbench-graph-additions:";

export type GraphAddition =
  | { kind: "resource"; term: string }
  | { kind: "statement"; subject: string; predicate: string; object: string }
  | { kind: "query"; query: string };

type QueueStorage = Pick<Storage, "getItem" | "removeItem">;
type WritableQueueStorage = Pick<Storage, "getItem" | "setItem">;

export function additionsKey(basePath: string, repositoryId: string, serverIdentity: string) {
  return `${ADDITIONS_PREFIX}${repositoryScope(basePath, repositoryId, serverIdentity)}`;
}

function isAddition(entry: unknown): entry is GraphAddition {
  const value = entry as Record<string, unknown>;
  if (!value || typeof value !== "object") return false;
  if (value.kind === "resource") return typeof value.term === "string" && parseNTriplesTerm(value.term) !== null;
  if (value.kind === "statement")
    return [value.subject, value.predicate, value.object].every(
      (term) => typeof term === "string" && parseNTriplesTerm(term) !== null,
    );
  if (value.kind === "query") return typeof value.query === "string" && value.query.trim().length > 0;
  return false;
}

/** Reads and empties the repository's queue; malformed entries are dropped. */
export function takeAdditions(basePath: string, repositoryId: string, storage?: QueueStorage, serverIdentity?: string): GraphAddition[] {
  // Older queues do not identify their server. Keep them for recovery without claiming them for today's connection.
  if (!serverIdentity) return [];
  let store: QueueStorage | undefined = storage;
  try {
    store ??= localStorage;
  } catch {
    return [];
  }
  const key = additionsKey(basePath, repositoryId, serverIdentity);
  let raw: string | null = null;
  try {
    raw = store.getItem(key);
    if (raw !== null) store.removeItem(key);
  } catch {
    return [];
  }
  if (!raw) return [];
  try {
    const parsed: unknown = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed.filter(isAddition) : [];
  } catch {
    return [];
  }
}

/** Puts additions that could not be applied (the user started something else) back at the front of the queue. */
export function returnAdditions(
  basePath: string,
  repositoryId: string,
  additions: readonly GraphAddition[],
  storage?: WritableQueueStorage,
  serverIdentity?: string,
) {
  if (!additions.length || !serverIdentity) return;
  try {
    const store = storage ?? localStorage;
    const key = additionsKey(basePath, repositoryId, serverIdentity);
    let queued: unknown = [];
    try {
      queued = JSON.parse(store.getItem(key) ?? "[]");
    } catch {
      queued = [];
    }
    store.setItem(key, JSON.stringify([...additions, ...(Array.isArray(queued) ? queued.filter(isAddition) : [])]));
  } catch {
    // Storage that cannot be written loses them, as it would have lost them before.
  }
}

function unescapeNTriples(text: string) {
  return text.replace(/\\(u[0-9A-Fa-f]{4}|U[0-9A-Fa-f]{8}|[tbnrf"'\\])/g, (_, escape: string) => {
    if (escape[0] === "u" || escape[0] === "U") return String.fromCodePoint(Number.parseInt(escape.slice(1), 16));
    return ({ t: "\t", b: "\b", n: "\n", r: "\r", f: "\f", '"': '"', "'": "'", "\\": "\\" } as Record<string, string>)[escape];
  });
}

const IRI = /^<([^<>"{}|^`\s]*)>$/;
const BLANK = /^_:(\S+)$/;
const LITERAL = /^"((?:[^"\\]|\\.)*)"(?:@([A-Za-z]+(?:-[A-Za-z0-9]+)*)(?:--(ltr|rtl))?|\^\^<([^<>"{}|^`\s]*)>)?$/s;

/** One N-Triples term as a SPARQL JSON term; null for triple terms (the graph does not draw them) and non-terms. */
export function parseNTriplesTerm(text: string): SparqlValue | null {
  const term = text.trim();
  const iri = IRI.exec(term);
  if (iri) return { type: "uri", value: unescapeNTriples(iri[1]) };
  const blank = BLANK.exec(term);
  if (blank) return { type: "bnode", value: blank[1] };
  const literal = LITERAL.exec(term);
  if (!literal) return null;
  const value = unescapeNTriples(literal[1]);
  if (literal[2]) {
    return {
      type: "literal",
      value,
      "xml:lang": literal[2],
      ...(literal[3] ? { "its:dir": literal[3] as "ltr" | "rtl" } : {}),
    };
  }
  if (literal[4]) return { type: "literal", value, datatype: unescapeNTriples(literal[4]) };
  return { type: "literal", value };
}

/** A queued statement as a ?source ?predicate ?target row, or null when it is not a statement the graph can draw. */
export function statementBinding(entry: Extract<GraphAddition, { kind: "statement" }>): Binding | null {
  const source = parseNTriplesTerm(entry.subject);
  const predicate = parseNTriplesTerm(entry.predicate);
  const target = parseNTriplesTerm(entry.object);
  if (!source || source.type === "literal" || predicate?.type !== "uri" || !target) return null;
  return { source, predicate, target };
}

/**
 * A query that answers queued statements again, recorded in the load history; statements with blank nodes are left
 * out (VALUES cannot name blank nodes). Empty when no statement can be written.
 */
export function statementsQuery(entries: Array<Extract<GraphAddition, { kind: "statement" }>>) {
  const rows = entries
    .filter((entry) => statementBinding(entry) && ![entry.subject, entry.object].some((term) => BLANK.test(term.trim())))
    .map((entry) => `  (${entry.subject.trim()} ${entry.predicate.trim()} ${entry.object.trim()})`);
  return rows.length ? `SELECT ?source ?predicate ?target WHERE { VALUES (?source ?predicate ?target) {\n${rows.join("\n")}\n} }` : "";
}
